  9	namespace UI\Icons;
 10	
 11	use AppUtils\FileHelper\JSONFile;
 12	
 13	/**
 14	 * Singleton registry of all available icons — both framework standard icons
 15	 * and application custom icons. On first access the collection loads and
 16	 * merges the two JSON sources, normalises IDs (hyphens/spaces → underscores),
 17	 * and sorts the result alphabetically by icon ID.
 18	 *
 19	 * Custom icons with the same ID as a standard icon replace the standard entry,
 20	 * allowing applications to override framework icons.
 21	 *
 22	 * @package UI
 23	 * @subpackage Icons
 24	 * @see IconInfo
 25	 */
 26	class IconCollection
 27	{
 28	    private static ?IconCollection $instance = null;
 29	
 30	    /**
 31	     * @var array<string,IconInfo>
 32	     */
 33	    private array $icons = array();
 34	
 35	    private function __construct()
 36	    {
 37	        $this->loadIcons();
 38	    }
 39	
 40	    public static function getInstance() : self
 41	    {
 42	        if(self::$instance === null)
 43	        {
 44	            self::$instance = new self();
 45	        }
 46	
 47	        return self::$instance;
 48	    }
 49	
 50	    /**
 51	     * Returns all available icons sorted alphabetically by ID.
 52	     *
 53	     * @return IconInfo[]
 54	     */
 55	    public function getAll() : array
 56	    {
 57	        return array_values($this->icons);
 58	    }
 59	
 60	    /**
 61	     * Returns only the framework standard icons, sorted alphabetically by ID.
 62	     *
 63	     * @return IconInfo[]
 64	     */
 65	    public function getStandardIcons() : array
 66	    {
 67	        $result = array();
 68	
 69	        foreach($this->icons as $icon)
 70	        {
 71	            if($icon->isStandard())
 72	            {
 73	                $result[] = $icon;
 74	            }
 75	        }
 76	
 77	        return $result;
 78	    }
 79	
 80	    /**
 81	     * Returns only the application custom icons, sorted alphabetically by ID.
 82	     *
 83	     * @return IconInfo[]
 84	     */
 85	    public function getCustomIcons() : array
 86	    {
 87	        $result = array();
 88	
 89	        foreach($this->icons as $icon)
 90	        {
 91	            if($icon->isCustom())
 92	            {
 93	                $result[] = $icon;
 94	            }
 95	        }
 96	
 97	        return $result;
 98	    }
