 30	    // -------------------------------------------------------------------------
 31	
 32	    public function test_getAll_includesFrameworkIcons() : void
 33	    {
 34	        $all = $this->collection()->getAll();
 35	
 36	        $this->assertNotEmpty($all);
 37	
 38	        $ids = array_map(
 39	            static function(IconInfo $icon) : string { return $icon->getID(); },
 40	            $all
 41	        );
 42	
 43	        $this->assertContains(self::STANDARD_ICON_ID, $ids);
 44	    }
 45	
 46	    public function test_getAll_includesCustomIcons() : void
 47	    {
 48	        $all = $this->collection()->getAll();
 49	
 50	        $ids = array_map(
 51	            static function(IconInfo $icon) : string { return $icon->getID(); },
 52	            $all
 53	        );
 54	
 55	        foreach(self::CUSTOM_ICON_IDS as $customID)
 56	        {
 57	            $this->assertContains($customID, $ids,
 58	                'Expected custom icon [' . $customID . '] to be present in getAll().'
 59	            );
 60	        }
 61	    }
 62	
 63	    // -------------------------------------------------------------------------
 64	    // getCustomIcons()
 65	    // -------------------------------------------------------------------------
 66	
 67	    public function test_getCustomIcons_returnsExactlyCustomIcons() : void
 68	    {
 69	        $custom = $this->collection()->getCustomIcons();
 70	
 71	        $this->assertCount(count(self::CUSTOM_ICON_IDS), $custom);
 72	
 73	        $returnedIDs = array_map(
 74	            static function(IconInfo $icon) : string { return $icon->getID(); },
 75	            $custom
 76	        );
 77	
 78	        sort($returnedIDs);
 79	        $expected = self::CUSTOM_ICON_IDS;
 80	        sort($expected);
 81	
 82	        $this->assertSame($expected, $returnedIDs);
 83	    }
 84	
 85	    public function test_getCustomIcons_allMarkedAsCustom() : void
 86	    {
 87	        foreach($this->collection()->getCustomIcons() as $icon)
 88	        {
 89	            $this->assertTrue(
 90	                $icon->isCustom(),
 91	                'Icon [' . $icon->getID() . '] returned by getCustomIcons() should have isCustom() === true.'
 92	            );
 93	        }
 94	    }
 95	
 96	    // -------------------------------------------------------------------------
 97	    // getStandardIcons()
 98	    // -------------------------------------------------------------------------
 99	
100	    public function test_getStandardIcons_containsNoCustomIcons() : void

101	    {
102	        $standard = $this->collection()->getStandardIcons();
103	
104	        $this->assertNotEmpty($standard);
105	
106	        $ids = array_map(
107	            static function(IconInfo $icon) : string { return $icon->getID(); },
108	            $standard
109	        );
110	
111	        foreach(self::CUSTOM_ICON_IDS as $customID)
112	        {
113	            $this->assertNotContains(
114	                $customID,
115	                $ids,
116	                'Custom icon [' . $customID . '] must not appear in getStandardIcons().'
117	            );
118	        }
119	    }
120	
121	    public function test_getStandardIcons_allMarkedAsStandard() : void
122	    {
123	        foreach($this->collection()->getStandardIcons() as $icon)
124	        {
125	            $this->assertTrue(
126	                $icon->isStandard(),
127	                'Icon [' . $icon->getID() . '] returned by getStandardIcons() should have isStandard() === true.'
128	            );
129	        }
130	    }
