132	    // -------------------------------------------------------------------------
133	    // getByID()
134	    // -------------------------------------------------------------------------
135	
136	    public function test_getByID_customIcon_isCustom() : void
137	    {
138	        $icon = $this->collection()->getByID('planet');
139	
140	        $this->assertTrue($icon->isCustom());
141	    }
142	
143	    public function test_getByID_standardIcon_isStandard() : void
144	    {
145	        $icon = $this->collection()->getByID(self::STANDARD_ICON_ID);
146	
147	        $this->assertTrue($icon->isStandard());
148	    }
149	
150	    public function test_getByID_createIcon_returnsUIIcon() : void
151	    {
152	        $icon = $this->collection()->getByID(self::STANDARD_ICON_ID)->createIcon();
153	
154	        $this->assertInstanceOf(UI_Icon::class, $icon);
155	    }
156	
157	    public function test_getByID_createIcon_setsCorrectType() : void
158	    {
159	        // 'add' maps to icon name 'plus-circle' with no prefix (defaults to 'fa').
160	        $icon = $this->collection()->getByID(self::STANDARD_ICON_ID)->createIcon();
161	
162	        $this->assertSame('plus-circle', $icon->getType());
163	        $this->assertSame('fa', $icon->getPrefix());
164	    }
165	
166	    public function test_getByID_throwsForUnknownID() : void
167	    {
168	        $this->expectException(\RuntimeException::class);
169	
170	        $this->collection()->getByID('nonexistent_icon_that_does_not_exist');
171	    }
172	
173	    // -------------------------------------------------------------------------
174	    // idExists()
175	    // -------------------------------------------------------------------------
176	
177	    public function test_idExists_returnsFalseForNonexistent() : void
178	    {
179	        $this->assertFalse($this->collection()->idExists('nonexistent'));
180	    }
181	
182	    public function test_idExists_returnsTrueForStandardIcon() : void
183	    {
184	        $this->assertTrue($this->collection()->idExists(self::STANDARD_ICON_ID));
185	    }
186	
187	    public function test_idExists_returnsTrueForCustomIcon() : void
188	    {
189	        $this->assertTrue($this->collection()->idExists('planet'));
190	    }
191	}

101	     * Checks whether an icon with the given ID exists in the collection.
102	     *
103	     * @param string $iconID
104	     * @return bool
105	     */
106	    public function idExists(string $iconID) : bool
107	    {
108	        return isset($this->icons[$iconID]);
109	    }
110	
111	    /**
112	     * Returns the {@see IconInfo} for the given icon ID.
113	     *
114	     * NOTE: The ID must be in its normalised form — hyphens and spaces
115	     * converted to underscores (e.g. `time_tracker`, not `time-tracker`).
116	     * To look up an icon using an un-normalised key, normalise it first:
117	     * `str_replace(array('-', ' '), '_', $id)`. Use {@see self::idExists()}
118	     * to test existence before calling this method.
119	     *
120	     * @param string $iconID Normalised icon ID (underscores, no hyphens/spaces).
121	     * @return IconInfo
122	     * @throws \RuntimeException When no icon with the given ID exists.
123	     */
124	    public function getByID(string $iconID) : IconInfo
125	    {
126	        if(isset($this->icons[$iconID]))
127	        {
128	            return $this->icons[$iconID];
129	        }
130	
131	        throw new \RuntimeException(sprintf(
132	            'No icon with ID [%s] found in the icon collection.',
133	            $iconID
134	        ));
135	    }
136	
137	    /**
138	     * Returns the total number of icons in the collection.
139	     *
140	     * @return int
141	     */
142	    public function countIcons() : int
143	    {
144	        return count($this->icons);
145	    }
146	
147	    /**
148	     * Loads icons from the framework JSON file and, if present, from the
149	     * application custom icons JSON file. Custom icons replace standard
150	     * icons with the same normalised ID.
151	     *
152	     * @return void
153	     */
154	    private function loadIcons() : void
155	    {
156	        $this->loadFromFile(
157	            APP_INSTALL_FOLDER . '/themes/default/icons.json',
158	            false
159	        );
160	
161	        $customPath = APP_ROOT . '/themes/custom-icons.json';
162	
163	        if(file_exists($customPath))
164	        {
165	            $this->loadFromFile($customPath, true);
166	        }
167	
168	        ksort($this->icons);
169	    }
170	
171	    /**
172	     * Parses a single icons JSON file and adds its entries to the collection.
173	     * Each icon ID is normalised by replacing hyphens and spaces with underscores.
174	     *
175	     * @param string $path     Absolute path to the JSON file.
176	     * @param bool   $isCustom Whether these icons are custom (application) icons.
177	     * @return void
178	     */
179	    private function loadFromFile(string $path, bool $isCustom) : void
180	    {
181	        $file = JSONFile::factory($path);
182	
183	        if(!$file->exists())
184	        {
185	            return;
186	        }
187	
188	        $data = $file->parse();
189	
190	        foreach($data as $rawID => $iconDef)
191	        {
192	            $id = IconInfo::normaliseID((string)$rawID);
193	
194	            $iconName = isset($iconDef['icon']) ? (string)$iconDef['icon'] : '';
195	            $prefix   = isset($iconDef['type']) ? (string)$iconDef['type'] : '';
196	
197	            $this->icons[$id] = new IconInfo($id, $iconName, $prefix, $isCustom);
198	        }
199	    }

